import React, { useState } from "react";
import FormWrapper from "./FormWrapper";

const FeasibilityReport = () => {
  const [formData, setFormData] = useState({
    slNo: "",
    date: "",
    fromDept: "",
    toDept: "",
    partName: "",
    partNo: "",
    customer: "",
    categoryOfChange: "",
    requirements: [
      { id: "mfg", title: "Manufacturing Process / Product Requirement", desc: "", feasibility: "" },
      { id: "sys", title: "System Requirement", desc: "", feasibility: "" },
      { id: "insp", title: "Inspection Requirement", desc: "", feasibility: "" },
      { id: "other", title: "Any Other Requirement", desc: "", feasibility: "" },
    ],
    resources: "",
    conclusion: "",
    conclusionNotes: "",
    cftMembers: Array.from({ length: 6 }, (_, index) => ({
      id: index + 1,
      name: "",
      date: "",
    })),
    comments: "",
    forwardedTo: "",
  });

  const [savedMsg, setSavedMsg] = useState("");

  const updateField = (field, value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const updateRequirement = (index, field, value) => {
    setFormData((prev) => ({
      ...prev,
      requirements: prev.requirements.map((item, i) =>
        i === index ? { ...item, [field]: value } : item
      ),
    }));
  };

  const updateMember = (index, field, value) => {
    setFormData((prev) => ({
      ...prev,
      cftMembers: prev.cftMembers.map((member, i) =>
        i === index ? { ...member, [field]: value } : member
      ),
    }));
  };

  const handleSave = () => {
    localStorage.setItem("saved_feasibility_report", JSON.stringify(formData));
    setSavedMsg("Feasibility report saved successfully!");
    window.setTimeout(() => setSavedMsg(""), 3000);
  };

  return (
    <FormWrapper
      title="FEASIBILITY REPORT FOR CHANGE REQUEST"
      qfNo="QF / 07 / MRO - 02"
      revDate="10 / 06 / 2015"
      onSave={handleSave}
      onPrint={() => window.print()}
    >
      {savedMsg && (
        <div className="mb-3 rounded border border-green-500 bg-green-50 p-2 text-sm font-bold text-green-800 print:hidden">
          {savedMsg}
        </div>
      )}

      <div className="w-full border-2 border-black bg-white text-black">
        {/* Serial number and date */}
        <div className="grid grid-cols-12 border-b-2 border-black">
          <div className="col-span-12 border-b-2 border-black p-2 sm:col-span-7 sm:border-b-0 sm:border-r-2">
            <label className="flex items-center gap-2 text-xs font-semibold">
              <span className="min-w-fit">SL. No (of Change Request) :</span>
              <input
                value={formData.slNo}
                onChange={(e) => updateField("slNo", e.target.value)}
                className="min-w-0 flex-1 border-b border-gray-400 bg-transparent px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
              />
            </label>
          </div>
          <div className="col-span-12 p-2 sm:col-span-5">
            <label className="flex items-center gap-2 text-xs font-semibold">
              <span>Date :</span>
              <input
                type="date"
                value={formData.date}
                onChange={(e) => updateField("date", e.target.value)}
                className="min-w-0 flex-1 border-b border-gray-400 bg-transparent px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
              />
            </label>
          </div>
        </div>

        {/* Form title */}
        <div className="border-b-2 border-black px-2 py-2 text-center">
          <h2 className="text-base font-bold uppercase tracking-wide sm:text-xl">
            FEASIBILITY REPORT FOR CHANGE REQUEST
          </h2>
        </div>

        {/* From / To */}
        <div className="grid grid-cols-12 border-b border-black">
          <div className="col-span-12 flex items-center border-b border-black px-3 py-1.5 sm:col-span-8 sm:border-b-0 sm:border-r">
            <label className="mr-2 min-w-fit text-xs font-semibold">FROM :</label>
            <input
              value={formData.fromDept}
              onChange={(e) => updateField("fromDept", e.target.value)}
              className="w-full bg-transparent px-1 text-sm outline-none"
            />
          </div>
          <div className="col-span-12 flex items-center px-3 py-1.5 sm:col-span-4">
            <label className="mr-2 text-xs font-semibold">TO :</label>
            <input
              value={formData.toDept}
              onChange={(e) => updateField("toDept", e.target.value)}
              className="w-full bg-transparent px-1 text-sm outline-none"
            />
          </div>
        </div>

        {/* Part and customer details */}
        {[
          ["Part Name :", "partName"],
          ["Part No :", "partNo"],
          ["Customer :", "customer"],
        ].map(([label, field]) => (
          <div key={field} className="flex min-h-[29px] items-center border-b border-black px-3 py-1">
            <label className="mr-2 min-w-[78px] text-xs font-semibold">{label}</label>
            <input
              value={formData[field]}
              onChange={(e) => updateField(field, e.target.value)}
              className="w-full bg-transparent px-1 text-sm outline-none"
            />
          </div>
        ))}

        {/* Category of change */}
        <div className="border-b-2 border-black px-3 py-2">
          <label className="block text-xs font-semibold uppercase">CATEGORY OF CHANGE</label>
          <span className="block text-xs">(as per the change request)</span>
          <input
            value={formData.categoryOfChange}
            onChange={(e) => updateField("categoryOfChange", e.target.value)}
            className="mt-1 w-full border-b border-gray-300 bg-transparent px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
          />
        </div>

        {/* Requirements table */}
        <div className="grid grid-cols-12 border-b-2 border-black text-center text-xs font-semibold">
          <div className="col-span-3 border-r-2 border-black px-1 py-2 sm:col-span-3" />
          <div className="col-span-6 border-r-2 border-black px-1 py-2 sm:col-span-6">
            REQUIREMENTS OF THE CHANGE
          </div>
          <div className="col-span-3 px-1 py-2 sm:col-span-3">
            FEASIBLE /<br /> NOT FEASIBLE
          </div>
        </div>

        {formData.requirements.map((req, index) => (
          <div key={req.id} className="grid min-h-[92px] grid-cols-12 border-b-2 border-black">
            <div className="col-span-3 flex items-center justify-center border-r-2 border-black px-2 py-2 text-center text-xs sm:col-span-3 sm:text-sm">
              {req.title}
            </div>
            <div className="col-span-6 border-r-2 border-black p-1 sm:col-span-6">
              <textarea
                rows={4}
                value={req.desc}
                onChange={(e) => updateRequirement(index, "desc", e.target.value)}
                className="h-full min-h-[78px] w-full resize-y bg-transparent p-1 text-sm leading-6 outline-none focus:ring-1 focus:ring-inset focus:ring-[#FF9800]"
                aria-label={`${req.title} details`}
              />
            </div>
            <div className="col-span-3 flex flex-col items-start justify-center gap-2 px-2 py-2 text-[10px] sm:col-span-3 sm:px-4 sm:text-xs">
              <label className="flex items-center gap-1.5">
                <input
                  type="radio"
                  name={`feasibility-${req.id}`}
                  checked={req.feasibility === "FEASIBLE"}
                  onChange={() => updateRequirement(index, "feasibility", "FEASIBLE")}
                  className="accent-[#FF9800]"
                />
                FEASIBLE
              </label>
              <label className="flex items-center gap-1.5">
                <input
                  type="radio"
                  name={`feasibility-${req.id}`}
                  checked={req.feasibility === "NOT FEASIBLE"}
                  onChange={() => updateRequirement(index, "feasibility", "NOT FEASIBLE")}
                  className="accent-[#FF9800]"
                />
                NOT FEASIBLE
              </label>
            </div>
          </div>
        ))}

        {/* Additional resource requirement */}
        <div className="min-h-[150px] border-b-2 border-black px-3 py-2">
          <label className="block max-w-[310px] text-xs leading-5">
            Additional Manufacturing or Inspection or other Resource requirement at Foundry / Machine Shop
          </label>
          <textarea
            rows={5}
            value={formData.resources}
            onChange={(e) => updateField("resources", e.target.value)}
            className="mt-2 min-h-[90px] w-full resize-y bg-transparent p-1 text-sm outline-none focus:ring-1 focus:ring-[#FF9800]"
          />
        </div>

        {/* Conclusion */}
        <div className="grid min-h-[120px] grid-cols-12 border-b-2 border-black">
          <div className="col-span-8 px-3 py-2 sm:col-span-9">
            <span className="text-xs font-semibold uppercase">CONCLUSION :</span>
            <textarea
              value={formData.conclusionNotes}
              onChange={(e) => updateField("conclusionNotes", e.target.value)}
              className="mt-2 min-h-[75px] w-full resize-y bg-transparent p-1 text-sm outline-none focus:ring-1 focus:ring-[#FF9800]"
              aria-label="Conclusion comments"
            />
          </div>
          <div className="col-span-4 flex flex-col justify-center gap-3 border-l-2 border-black px-2 sm:col-span-3 sm:px-4">
            <label className="flex items-center gap-2 text-xs">
              <input
                type="radio"
                name="conclusion"
                checked={formData.conclusion === "FEASIBLE"}
                onChange={() => updateField("conclusion", "FEASIBLE")}
                className="h-5 w-5 accent-[#FF9800]"
              />
              FEASIBLE
            </label>
            <label className="flex items-center gap-2 text-xs">
              <input
                type="radio"
                name="conclusion"
                checked={formData.conclusion === "NOT FEASIBLE"}
                onChange={() => updateField("conclusion", "NOT FEASIBLE")}
                className="h-5 w-5 accent-[#FF9800]"
              />
              NOT FEASIBLE
            </label>
          </div>
        </div>

        {/* CFT members: numbered blank signing areas */}
        <div className="grid min-h-[105px] grid-cols-12 border-b-2 border-black">
          <div className="col-span-3 flex items-start justify-center border-r-2 border-black px-2 py-2 text-center text-xs font-semibold sm:col-span-3">
            CFT MEMBERS SIGN /<br /> DATE
          </div>
          <div className="col-span-9 grid grid-cols-2 gap-x-4 px-3 py-1 sm:col-span-9">
            {[0, 1, 2, 3, 4, 5].map((index) => (
              <div key={index} className="flex min-h-[32px] items-center gap-2">
                <span className="w-4 text-xs">{index + 1}.</span>
                <input
                  value={formData.cftMembers[index].name}
                  onChange={(e) => updateMember(index, "name", e.target.value)}
                  className="min-w-0 flex-1 border-b border-transparent bg-transparent px-1 text-xs outline-none focus:border-[#FF9800]"
                  aria-label={`CFT member ${index + 1} name or signature`}
                />
                <input
                  type="date"
                  value={formData.cftMembers[index].date}
                  onChange={(e) => updateMember(index, "date", e.target.value)}
                  className="w-[88px] border-b border-transparent bg-transparent text-[9px] outline-none focus:border-[#FF9800] sm:w-[105px]"
                  aria-label={`CFT member ${index + 1} date`}
                />
              </div>
            ))}
          </div>
        </div>

        {/* Comments and forwarded-to area */}
        <div className="grid min-h-[115px] grid-cols-12">
          <div className="col-span-7 border-r-2 border-black sm:col-span-7">
            <label className="block px-3 py-1.5 text-xs font-semibold">COMMENTS :</label>
            <textarea
              value={formData.comments}
              onChange={(e) => updateField("comments", e.target.value)}
              className="min-h-[80px] w-full resize-y bg-transparent px-3 py-1 text-sm outline-none focus:ring-1 focus:ring-inset focus:ring-[#FF9800]"
              aria-label="Comments"
            />
          </div>
          <div className="col-span-5">
            <label className="block px-3 py-1.5 text-xs font-semibold">FORWARDED TO :</label>
            <textarea
              value={formData.forwardedTo}
              onChange={(e) => updateField("forwardedTo", e.target.value)}
              className="min-h-[80px] w-full resize-y bg-transparent px-3 py-1 text-sm outline-none focus:ring-1 focus:ring-inset focus:ring-[#FF9800]"
              aria-label="Forwarded to"
            />
          </div>
        </div>
      </div>
    </FormWrapper>
  );
};

export default FeasibilityReport;
